// Atlas extraction / alpha cleanup only. Illustration is generated by imagegen.
import fs from 'node:fs';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url);
const {PNG}=require('C:/Users/fuweicheng/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/pngjs');
const sharp=require('C:/Users/fuweicheng/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/sharp');
const root='assets/builds',source=PNG.sync.read(fs.readFileSync(`${root}/source/effects-chroma.png`));
const bounds=[[0,80,525,500],[525,80,500,500],[1025,80,511,500],[0,600,525,424],[525,600,500,424],[1025,600,511,424]];
const names=['aegis','bloodspin','inferno','icelance','markedshot','shadow'];
const manifest={version:1,source:'source/effects-chroma.png',frames:{}};
for(let n=0;n<names.length;n++){
 const [sx,sy,sw,sh]=bounds[n],im=new PNG({width:sw,height:sh});PNG.bitblt(source,im,sx,sy,sw,sh,0,0);
 let left=sw,top=sh,right=0,bottom=0;
 for(let y=0;y<sh;y++)for(let x=0;x<sw;x++){
  const i=(y*sw+x)*4,[r,g,b]=im.data.subarray(i,i+3);
  // Generated chroma is pink; purple inks have much lower red or high green highlights.
  if(r>168&&b>174&&g<110&&Math.abs(r-b)<87){im.data.fill(0,i,i+4);continue;}
  if(im.data[i+3]>0){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}
 }
 const pad=4,w=right-left+1+pad*2,h=bottom-top+1+pad*2,out=new PNG({width:w,height:h});
 PNG.bitblt(im,out,left,top,w-pad*2,h-pad*2,pad,pad);fs.writeFileSync(`${root}/${names[n]}.png`,PNG.sync.write(out));
 manifest.frames[names[n]]={file:`${names[n]}.png`,width:w,height:h,anchor:[.5,.5]};
 console.log(`${names[n]} ${w}x${h}`);
}
// The independent cold field came back with real alpha. Preserve that alpha;
// trim its transparent border and resize the whole sprite once for distribution.
const fieldPath=`${root}/source/coldfield.png`,field=PNG.sync.read(fs.readFileSync(fieldPath));
let left=field.width,top=field.height,right=0,bottom=0;
for(let y=0;y<field.height;y++)for(let x=0;x<field.width;x++)if(field.data[(y*field.width+x)*4+3]>8){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}
await sharp(fieldPath).extract({left,top,width:right-left+1,height:bottom-top+1}).resize(632,632,{fit:'contain',background:{r:0,g:0,b:0,alpha:0}}).extend({top:4,bottom:4,left:4,right:4,background:{r:0,g:0,b:0,alpha:0}}).png().toFile(`${root}/coldfield.png`);
manifest.frames.coldfield={file:'coldfield.png',width:640,height:640,anchor:[.5,.5],source:'source/coldfield.png'};
console.log('coldfield 640x640; generated alpha preserved');
fs.writeFileSync(`${root}/manifest.json`,JSON.stringify(manifest,null,2)+'\n');
